<span class="line"><span style="color:#DFA000;--shiki-dark:#DBBC7F">    :is-resizable</span><span style="color:#8DA101;--shiki-dark:#A7C080">=</span><span style="color:#8DA101;--shiki-dark:#A7C080">"!isLock"</span></span>
