<span class="line"><span style="color:#35A77C;--shiki-dark:#83C092">  transition</span><span style="color:#939F91;--shiki-dark:#859289">:</span><span style="color:#8DA101;--shiki-dark:#A7C080"> all 0.4</span><span style="color:#F57D26;--shiki-dark:#E69875">s</span><span style="color:#939F91;--shiki-dark:#859289">;</span></span>
